$(".calc__range").on("input", function () {
	var amount = pow($(this).val(), 2);
	$('.calc__amount').val(amount);
	var data = sw(amount);
	calc(data, amount);
}).trigger("change");

$(document).on('change keyup', '.calc__amount', function () {
	
	var amount = Number($(this).val() * Math.pow(10, 2)) / Math.pow(10, 2);
	$('.calc__range').val($(this).val());
	var data = sw(amount);
	if (amount > data.max) {
		amount = data.max;
		$(this).val(amount);
	}
	calc(data, amount);
}).on('keypress', '.calc__amount', isNumberKey);

function sw(amount) {
	var data = [];
	data.min = 20;
	data.max = 10000;
	data.duration = 12;
	data.percent =10;
	data.total = 120;
	data.acrual = 12;
	data.deposit = 0;
	data.plan = 1;
	if (amount > 1000 && amount <= 10000) {
		data.duration = 12;
		data.percent = 12;
		data.acrual = 12;
		data.total = 144;
		data.plan = 2;
	}
	console.log(data);
	return data;
}

function calc(data, amount) {
	if (jQuery.isEmptyObject(data)) {
		data = sw();
		amount = data.min;
		$('.calc__amount').val(data.min);
		calculate(amount, data.percent, data.duration, data.deposit, data.plan,  data.min, data.acrual, data.total);
	}
	calculate(amount, data.percent, data.duration, data.deposit, data.plan,  data.min, data.acrual, data.total);
}

function calculate(amount, percent, duration, deposit, plan,  min, acrual, total) {
	var plan = plan;
	var acrual = acrual;
	var sum = Number(amount);
	var percent = Number(percent);
	var duration = Number(duration);
	var deposit = Number(deposit);


	$('.sd-plans__item:not(.sd-plans__item--deposit)').removeClass('sd-plans__item--active');
	$('.sd-plans__item--' + plan +':not(.sd-plans__item--deposit)').addClass('sd-plans__item--active');
	
	var result1 = pow( sum * percent / 100, 2);
	var result2 = pow(sum * deposit + (sum) * total / 100, 2);
	
	if (Number($('.dailyProfit').html()) != result1) {
		$('.dailyProfit').animateNumbers($('.dailyProfit').html(), result1, 400, null, 2);
	}
	if (Number($('.totalReturn').html()) != result2) {
		$('.totalReturn').animateNumbers($('.totalReturn').html(), result2, 400, null, 2);
	}
}




