$(function () {
	function copytext(el) {
			var $tmp = $('<input>');
			$('body').append($tmp);
			if ($(el).is("input")) {
					$tmp.val($(el).val()).select();
			} else {
					$tmp.val($(el).text()).select();
			}
			document.execCommand('copy');
			$tmp.remove();
	}

	function setupCopyFeature() {
			$(document).on('click', '.copy-link .btn-copy', function () {
					copytext($(this).parent().parent().find('.copy-value'));

					toastr.success('Copied to clipboard!', {
							closeButton: false,
							progressBar: true,
							positionClass: 'toast-bottom-right',
							timeOut: '3000',  
							showEasing: 'swing',
							showMethod: 'fadeIn',
							hideMethod: 'fadeOut'
					});
			});
	}

	setupCopyFeature();
});
