$(document).ready(function() {
	const numDots = 150;
	const $animationArea = $('#animation-area');
	const areaWidth = $animationArea.width();
	const areaHeight = $animationArea.height();
	const centerX = areaWidth / 2;
	const centerY = areaHeight / 2;
	const maxRadiusX = areaWidth / 2 - 20; // Максимальный радиус по оси X
	const maxRadiusY = areaHeight / 2 - 20; // Максимальный радиус по оси Y

	// Функция для создания случайного цвета и прозрачности
	function getRandomColor() {
			const colors = ['rgba(255, 255, 255, ', 'rgba(157, 96, 250, '];
			const color = colors[Math.floor(Math.random() * colors.length)];
			const opacity = Math.random().toFixed(2);
			return color + opacity + ')';
	}

	// Функция для создания точки
	function createDot() {
			const angle = Math.random() * 2 * Math.PI;
			const radiusX = Math.random() * maxRadiusX;
			const radiusY = Math.random() * maxRadiusY;
			const dot = $('<div class="dot"></div>').css({
					backgroundColor: getRandomColor(),
					transform: `translate(${centerX + radiusX * Math.cos(angle)}px, ${centerY + radiusY * Math.sin(angle)}px)`
			});
			$animationArea.append(dot);
			return { dot, radiusX, radiusY, angle };
	}

	// Создаем точки
	const dots = [];
	for (let i = 0; i < numDots; i++) {
			dots.push(createDot());
	}

	// Функция для анимации точек по круговой траектории
	function animateDots() {
			dots.forEach(dotObj => {
					const { dot, radiusX, radiusY } = dotObj;
					const duration = Math.random() * 500 + 1000; // случайная скорость от 1 до 1.5 секунд
					dotObj.angle += 0.1; // Увеличиваем угол для движения по кругу
					const newTop = centerY + radiusY * Math.sin(dotObj.angle);
					const newLeft = centerX + radiusX * Math.cos(dotObj.angle);
					dot.css({
							transition: `transform ${duration}ms linear`,
							transform: `translate(${newLeft}px, ${newTop}px)`
					});
			});

			setTimeout(animateDots, 1000);
	}

	// Запускаем анимацию
	animateDots();
});

if ($('input[name="email"]').length) {
	$('input[name="email"]').on('change keyup', function (event) {
		$(this).parent().find('input[name="email1"]').val($(this).val());
		event.preventDefault();
	});
}
if ($('ul.errors-list, ul.success-list, ul.redirect-list').length) {

	$('ul.errors-list, ul.success-list, ul.redirect-list').each(function() {
		var isErrors = $(this).hasClass('errors-list');
		var isRedirect = $(this).hasClass('redirect-list');

		$(this).find('li').each(function() {
				var message = $(this).text();

				var options = {
					closeButton: true,
					debug: false,
					newestOnTop: false,
					progressBar: true,
					positionClass: 'toast-bottom-right',
					preventDuplicates: false,
					onclick: null,
					showDuration: '300',
					hideDuration: '1000',
					timeOut: '5000',
					extendedTimeOut: '1000',
					showEasing: 'swing',
					hideEasing: 'linear',
					showMethod: 'fadeIn',
					hideMethod: 'fadeOut'
				};
				
				if (isRedirect) {
					toastr.info(message, "Redirect Notice", options);
				} else if (isErrors) {
						toastr.error(message, "Error", options); 
				} else {
						toastr.success(message, "Success", options); 
				}
		});
	});


}


if ($('.faq').length) {
	
	$(document).on('click', '.faq__item', function (event) {
			event.stopPropagation(); // Предотвратить всплытие события
			var parentItem = $(this).closest('.faq__item');
			$('.faq__item.active').not(parentItem).removeClass('active').find('.faq__text').slideUp('400');
			parentItem.toggleClass('active').find('.faq__text').slideToggle('400');
	});
}

$.fn.addClassDelay = function (className, delay) {
	var $addClassDelayElement = $(this),
		$addClassName = className;
	setTimeout(function () {
		$addClassDelayElement.addClass($addClassName);
	}, delay);
};

$.fn.removeClassDelay = function (className, delay) {
	var $addClassDelayElement = $(this),
		$addClassName = className;
	setTimeout(function () {
		$addClassDelayElement.removeClass($addClassName);
	}, delay);
};

$.fn.animateNumbers = function (start, stop, duration, ease, number = 2, delay = 0) {
	return this.each(function () {
		var $this = $(this);
		$({ Counter: start }).stop(true, true).delay(delay).animate({ Counter: stop }, {
			duration: duration == undefined ? 1000 : duration,
			easing: ease == undefined ? "swing" : ease,
			step: function () {
				$this.text(number_format(this.Counter, number, '.', ','));
			},
			complete: function () {
				$this.text(number_format(stop, number, '.', ','));
			}
		});
	});
};

function number_format(number, decimals, decPoint, thousandsSep) {

	number = (number + '').replace(/[^0-9+\-Ee.]/g, '')
	var n = !isFinite(+number) ? 0 : +number
	var prec = !isFinite(+decimals) ? 0 : Math.abs(decimals)
	var sep = (typeof thousandsSep === 'undefined') ? ',' : thousandsSep
	var dec = (typeof decPoint === 'undefined') ? '.' : decPoint
	var s = ''

	var toFixedFix = function (n, prec) {
		if (('' + n).indexOf('e') === -1) {
			return +(Math.round(n + 'e+' + prec) + 'e-' + prec)
		} else {
			var arr = ('' + n).split('e')
			var sig = ''
			if (+arr[1] + prec > 0) {
				sig = '+'
			}
			return (+(Math.round(+arr[0] + 'e' + sig + (+arr[1] + prec)) + 'e-' + prec)).toFixed(prec)
		}
	}

	s = (prec ? toFixedFix(n, prec).toString() : '' + Math.round(n)).split('.')
	if (s[0].length > 3) {
		s[0] = s[0].replace(/\B(?=(?:\d{3})+(?!\d))/g, sep)
	}
	if ((s[1] || '').length < prec) {
		s[1] = s[1] || ''
		s[1] += new Array(prec - s[1].length + 1).join('0')
	}

	return s.join(dec)
}


function isNumberKey(event) {
	var charCode = (event.which) ? event.which : event.keyCode;
	if (charCode == 46) return true;
	if (charCode > 31 && (charCode < 48 || charCode > 57))
		return false;
	return true;
}

function pow(amount, pow) {
	return Math.round(amount * Math.pow(10, pow)).toFixed(0) / Math.pow(10, pow);
}



