$("#toTop").click(function () {
	$("html, body").animate({ scrollTop: 0 }, 1000);
});
var viewportmeta = document.querySelector('meta[name="viewport"]');
		if (viewportmeta) {
			if (screen.width < 375) {
				var newScale = screen.width / 375;
				viewportmeta.content = 'width=375, minimum-scale=' + newScale + ', maximum-scale=1.0, user-scalable=no, initial-scale=' + newScale + '';
			} else {
				viewportmeta.content = 'width=device-width, maximum-scale=1.0, initial-scale=1.0';
			}
		}
		

(function () {
	const parallax = $('.js-parallax');
	if (parallax.length) {
			parallax.each(function(){
					const _this = $(this),
								scale = _this.data('scale'),
								orientation = _this.data('orientation');

					new simpleParallax(_this[0], {
							scale: scale,
							orientation: orientation,
							delay: .4,
							overflow: true,
							transition: 'cubic-bezier(0,0,0,1)'
					});
			});
	}
}());

if ($('.pincode-input').length) {
	$('.pincode-input').pincodeInput({inputs:4});
}


var tooltipTriggerList = [].slice.call(document.querySelectorAll('[data-bs-toggle="tooltip"]'))
var tooltipList = tooltipTriggerList.map(function (tooltipTriggerEl) {
  return new bootstrap.Tooltip(tooltipTriggerEl)
})

$(document).ready(function() {
	$('.button').on('mousemove', function(e) {
			const $this = $(this);
			const $round = $this.find('.round');
			const offset = $this.offset();
			const posX = e.pageX - offset.left ;
			const posY = e.pageY - offset.top ;

			$round.css('transform', `translate(${posX}px, ${posY}px)`);
	});

	$('.sd-plans__item').on('mousemove', function(e) {
		const $this = $(this);
		const $round = $this.find('.round');
		const offset = $this.offset();
		const posX = e.pageX - offset.left - 150;
		const posY = e.pageY - offset.top - 150;

		$round.css('transform', `translate(${posX}px, ${posY}px)`);
});

});
